"""The auto-generated file adapter, assembled for one row.

The user service serves the file actions. What only user, session or folder work reaches
is left unwired.
"""

from __future__ import annotations

from typing import Any

import pytest

from ai.backend.common.clients.valkey_client.valkey_stat.client import ValkeyStatClient
from ai.backend.common.data.entity.auto_generated_file import AutoGeneratedFileEntityType
from ai.backend.manager.actions.monitors import ActionMonitors
from ai.backend.manager.actions.registry.registry import ProcessorRegistry
from ai.backend.manager.actions.registry.types import (
    Concern,
    ConcernMeta,
    GroupMeta,
    ProcessorDependencies,
)
from ai.backend.manager.actions.v2.validators import ActionValidators as V2ActionValidators
from ai.backend.manager.api.adapters.auto_generated_file.adapter import AutoGeneratedFileAdapter
from ai.backend.manager.clients.storage_proxy.session_manager import StorageSessionManager
from ai.backend.manager.models.utils import ExtendedAsyncSAEngine
from ai.backend.manager.registry import AgentRegistry
from ai.backend.manager.repositories.auto_generated_file.repository import (
    AutoGeneratedFileRepository,
)
from ai.backend.manager.repositories.ops.repository import OpsRepository
from ai.backend.manager.repositories.ops.v2.provider import V2DBOpsProvider
from ai.backend.manager.repositories.user.repository import UserRepository
from ai.backend.manager.services.auto_generated_file.processors import (
    AutoGeneratedFileProcessors,
)
from ai.backend.manager.services.user.service import UserService
from ai.backend.manager.sokovan.scheduling_controller.scheduling_controller import (
    SchedulingController,
)
from bai_scenario.runner.unwired import unwired


@pytest.fixture
async def auto_generated_file_adapter(
    engine: ExtendedAsyncSAEngine,
    validators: V2ActionValidators,
    monitors: ActionMonitors,
) -> AutoGeneratedFileAdapter:
    provider = V2DBOpsProvider(engine)
    registry: ProcessorRegistry[Any] = ProcessorRegistry(
        ProcessorDependencies(
            monitors=monitors, validators=validators, repository=OpsRepository(provider)
        )
    )
    service = UserService(
        unwired(StorageSessionManager, "only purging a user with folders reaches it"),
        unwired(ValkeyStatClient, "no file operation reads user statistics"),
        unwired(AgentRegistry, "no file operation reaches the agents"),
        unwired(UserRepository, "no file operation reads users"),
        unwired(SchedulingController, "no file operation schedules sessions"),
        AutoGeneratedFileRepository(provider),
    )
    return AutoGeneratedFileAdapter(
        AutoGeneratedFileProcessors(
            registry.concern(ConcernMeta(Concern.AUTO_GENERATED_FILE)).group(
                GroupMeta(AutoGeneratedFileEntityType())
            ),
            service,
        )
    )
